/// The payload a Provider guest returns from its assemble_boundary export: the serialized bytes of each assembled file, any diagnostics the guest raised while assembling, and whether the orchestrator nests each contributor's per-node files under a per-node sub-directory. The guest returns each file's serialized bytes; the host writes them verbatim and runs no serializer. Determinism is the guest's responsibility: identical input must produce identical bytes.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct AssembleBoundaryOutput {
    /// The assembled output files the guest emitted, in emission order. Each names its on-disk path and carries the serialized bytes the host writes verbatim.
    pub files: Vec<RenderedFile>,
    /// Diagnostics the guest raised while assembling. Each element carries the shared Wasm-plugin diagnostic shape; the element shape is opaque at this schema layer so a guest emits the shared diagnostic without the provider socket schema rebinding it.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub diagnostics: Vec<Box<RawValue>>,
    /// Whether the orchestrator nests each contributor's per-node files under charts/<nodeID>/ rather than emitting them flat; the assembler signals this per provider (compose emits flat, so false; an umbrella-chart assembler nests, so true).
    #[serde(default, skip_serializing_if = "is_default")]
    pub nest_per_node: bool,
}

/// The payload a Provider guest receives on its optional carve export: one named output file the pipeline carves into addressable units before a FeatureRecipe step edits some of them. A provider whose output shape the stock YAML codec cannot carve directly (a templated chart, for instance) advertises carve and reassemble so its own output-shape knowledge lives in the guest; a provider that omits the exports borrows the host's stock YAML codec.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct CarveInput {
    /// The output file's name, so the codec can apply any name-scoped carving rule.
    pub name: String,
    /// The output file's bytes to carve into addressable units (base64 on the JSON wire).
    pub body: String,
    /// The indentation width the codec uses when it must synthesize new structured text; carried so the guest's carving matches the render-wide indentation.
    #[serde(default, skip_serializing_if = "is_default")]
    pub yaml_indent: i64,
}

/// The payload a Provider guest returns from its carve export: the ordered addressable units it carved the file into. A structured unit carries a tree (a PATCH target); an opaque unit carries only its media type and bytes.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct CarveOutput {
    /// The ordered addressable units the guest carved the file into.
    pub units: Vec<Box<RawValue>>,
}

/// The payload a Provider guest receives on its optional reassemble export: the original file plus its carved units and the patched units a pipeline step produced, so the guest splices the changes back into the original bytes surgically. A token absent from the patched set is re-joined from its original bytes verbatim; a patched token has only its addressed byte-spans edited.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct ReassembleInput {
    /// The output file's name, matching the name the same file was carved under.
    pub name: String,
    /// The original file bytes the reassembly splices the patched units back into (base64 on the JSON wire).
    pub body: String,
    /// The units the file was carved into, as carve returned them.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub segs: Vec<Box<RawValue>>,
    /// The units a pipeline step changed, each carrying its token, patched tree, and the ops that produced the change.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub patched: Vec<Box<RawValue>>,
    /// The indentation width the codec uses when an op must synthesize new structured text; carried so the reassembly matches the render-wide indentation.
    #[serde(default, skip_serializing_if = "is_default")]
    pub yaml_indent: i64,
}

/// The payload a Provider guest returns from its reassemble export: the file's bytes with the patched units spliced back in. Reassembly is byte-faithful — every byte the ops did not touch survives verbatim.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct ReassembleOutput {
    /// The reassembled file bytes the host writes verbatim (base64 on the JSON wire).
    pub body: String,
}

/// The payload a Provider guest receives on its optional boundary_env_overrides export: a boundary's internal uses edges and the driving feature's resolved infra, from which the guest computes per-consumer environment overrides for the boundary-to-consumer env channel. A guest whose provider drives that channel (a compose guest bridging cross-network endpoints) advertises the export; a provider that drives no such channel omits it, and the host applies no overrides for it. The edges and infra are opaque at this schema layer — the guest reads their shapes through the template-context wire contract; the schema does not interpret them.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct BoundaryEnvOverridesInput {
    /// The boundary's internal uses edges — the directed edges whose endpoints both live inside the boundary's subtree, each enriched with the producer's provides and the consumer's inject mapping. The guest reads them to decide which consumers need an env override and what value to write. Opaque at this schema layer; the guest reads the enriched-edge shape through the template-context wire contract.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub internal_uses_edges: Vec<Box<RawValue>>,
    /// The driving feature's resolved infra, an author-ordered key set the guest reads for the channel's tunables (for a compose bridge, the listen-port base and the upstream host provides-field selector). Preserves author order so the payload is byte-identical across runs of identical input.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub infra: BTreeMap<String, Box<RawValue>>,
}

/// The payload a Provider guest returns from its boundary_env_overrides export: the per-consumer environment overrides the host applies to each named consumer's injected env after the per-node render pass. The values are opaque strings the host carries without interpretation; a consumer absent from the map is left untouched.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct BoundaryEnvOverridesOutput {
    /// The per-consumer environment overrides, keyed by consumer node id to a map of environment-variable name to override value. An empty or absent map means the guest computed no overrides.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub overrides: BTreeMap<String, BTreeMap<String, String>>,
}

/// One endpoint of a cross-boundary link: the node, the boundary path its rendered output assembles into, and the provider that rendered it. The two endpoints of a link name the consuming and consumed ends of a uses edge whose ends assemble into different dispatch groups.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct LinkEndpoint {
    /// The endpoint node's absolute id within the topology graph.
    pub node: String,
    /// The endpoint's boundary path — the dispatch group its rendered output assembles into.
    pub boundary: String,
    /// The provider that rendered the endpoint (the provider engine name). Both endpoints of a wired link name the same provider; the host does not route a link whose endpoints name different providers.
    pub provider: String,
    /// The deployment identity the endpoint's rendered output belongs to — the scope its assembled artifacts are named within. The host assembles it from the build's deployment identity and passes it verbatim; it infers no meaning from the value. A provider reads it to scope a cross-reference name to the deployment. An absent value is the empty string, which a provider treats as an unscoped name.
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub deployment: String,
}

/// The generalized, domain-blind per-edge payload the host assembles for a uses edge whose consuming and consumed ends assemble into different dispatch groups. It carries both endpoints, both endpoints' placement annotations as opaque scalar maps the host does not interpret, the consumed endpoint's provides output, and the socket and inject mapping the edge wires. A provider reads it to produce the provider-native cross-reference wiring the two ends need; the host assembles it and passes the annotation map as opaque scalars, inferring no meaning from any value.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct LinkEdge {
    /// The consuming endpoint — the source end of the directed uses edge, whose assembled output the consumer-side wiring is injected into.
    pub source: LinkEndpoint,
    /// The consumed endpoint — the target end the uses edge points at, whose assembled output the producer-side wiring publishes.
    pub target: LinkEndpoint,
    /// The consumed (target) endpoint's placement annotations as an opaque scalar map, keyed by annotation name. The host assembles them from the target's resolved annotations and passes them verbatim; it infers no meaning from any value. A provider reads them to decide how to shape a cross-reference (for example whether the two ends share a placement or need a cross-placement reference). Keys serialize in sorted order so the payload is byte-identical across runs of identical input.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub target_annotations: BTreeMap<String, String>,
    /// The consuming (source) endpoint's placement annotations as an opaque scalar map, keyed by annotation name. The host assembles them from the source's resolved annotations and passes them verbatim; it infers no meaning from any value. A provider reads them to compare the two ends' placement — for example whether the source and target share a placement or sit in different ones. Keys serialize in sorted order so the payload is byte-identical across runs of identical input.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub source_annotations: BTreeMap<String, String>,
    /// The socket alias the uses edge is bound under.
    pub socket: String,
    /// The consumed endpoint's provides output, an author-ordered key set exposing the target's declared outputs. Preserves author order so the payload is byte-identical across runs of identical input.
    pub provides: BTreeMap<String, String>,
    /// The consuming endpoint's inject mapping, keyed by delivery mechanism to an author-ordered key set, describing how the consuming end receives the consumed endpoint's output. Preserves author order so the payload is byte-identical across runs of identical input.
    pub inject: BTreeMap<String, BTreeMap<String, String>>,
}

/// One per-file structural patch a provider returns as artifact wiring: the output file and the ordered structural operations to apply to it. A later host pass carves the named file, applies the operations, and reassembles it byte-faithfully. The operation shape is the shared pipeline patch-operation vocabulary; it is opaque at this schema layer, so a guest carries each operation verbatim while the host realizes the typed operation its pipeline applies.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct LinkPatch {
    /// The output file the operations apply to, named as the provider emitted it.
    pub file: String,
    /// The ordered structural operations to apply to the file, in application order.
    pub ops: Vec<Box<RawValue>>,
}

/// The payload a provider receives on its link_publish export: one cross-boundary link whose consumed endpoint's output is referenced across a boundary. The export returns the published identity the consumer resolves against and any producer-side artifact wiring the consumed endpoint's output needs.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct LinkPublishInput {
    /// The cross-boundary link being published, read from the consumed (target) endpoint's side.
    pub edge: LinkEdge,
}

/// The payload a provider returns from its link_publish export: the published identity handle the consumer resolves against, and the producer-side artifact wiring to apply to the consumed endpoint's assembled output.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct LinkPublishOutput {
    /// The published identity the consumed endpoint exposes for the consumer to resolve against, an opaque deterministic-pointer string map keyed by field name (for example an export name, a stack name, a region, a role reference). The values are deterministic pointer strings the compiler pipes and never resolves; the runtime environment resolves them at deploy time. Keys serialize in sorted order so the payload is byte-identical across runs of identical input.
    pub handle: BTreeMap<String, String>,
    /// The producer-side artifact wiring, one structural patch per consumed-endpoint output file the publish must edit. Empty when the consumed endpoint's output needs no change for the link.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub patches: Vec<LinkPatch>,
}

/// The payload a provider receives on its link_resolve export: one cross-boundary link, the published identity handle its consumed endpoint exposed, and the consuming endpoint's assembled files. The export returns the consumer-side artifact wiring that injects the reference into the consuming endpoint's assembled output.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct LinkResolveInput {
    /// The cross-boundary link being resolved, read from the consuming (source) endpoint's side.
    pub edge: LinkEdge,
    /// The published identity handle the consumed endpoint's link_publish returned, which the consumer resolves its reference against. Opaque deterministic-pointer strings keyed by field name; the compiler pipes them and never resolves them. Keys serialize in sorted order so the payload is byte-identical across runs of identical input.
    pub handle: BTreeMap<String, String>,
    /// The consuming endpoint's assembled files, so the provider can locate the placeholder the host stamped into the consuming output and author its replacement at the placeholder's real path. Each names its on-disk path and carries the assembled bytes. Absent when the host has no assembled consumer output to hand the resolve; a provider that needs no document to author its wiring ignores it.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub consumer_files: Vec<RenderedFile>,
}

/// The payload a provider returns from its link_resolve export: the consumer-side artifact wiring to apply to the consuming endpoint's assembled output, injecting the reference to the consumed endpoint's published identity.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct LinkResolveOutput {
    /// The consumer-side artifact wiring, one structural patch per consuming-endpoint output file the resolve must edit.
    pub patches: Vec<LinkPatch>,
}

